from jsonb_to_recordset($q$[{"id": 10447, "materia": "adm", "nivel": 0, "enunciado": "O servidor que aceita um presente caro de quem tem interesse no processo que ele analisa fere o princípio da:", "opcoes": ["Moralidade", "Publicidade", "Eficiência", "Hierarquia"], "explicacao": "Conduta contrária à ética e à probidade."}, {"id": 10448, "materia": "adm", "nivel": 0, "enunciado": "Publicar no site da prefeitura os contratos assinados atende ao princípio da:", "opcoes": ["Publicidade", "Impessoalidade", "Eficiência", "Hierarquia"], "explicacao": "Transparência dos atos."}, {"id": 10449, "materia": "adm", "nivel": 0, "enunciado": "Nomear o próprio filho para cargo de confiança no órgão que você chefia é:", "opcoes": ["Nepotismo, que é proibido", "Permitido, por ser cargo em comissão", "Permitido, se o filho tiver diploma", "Permitido, se o salário for baixo"], "explicacao": "Súmula Vinculante 13 do STF."}, {"id": 10450, "materia": "adm", "nivel": 0, "enunciado": "O concurso público garante principalmente:", "opcoes": ["Igualdade de acesso aos cargos", "Estabilidade imediata no cargo", "Salário maior que o do mercado", "Promoção automática na carreira"], "explicacao": "Art. 37, II, da CF."}, {"id": 10451, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, o ensino fundamental na rede pública é:", "opcoes": ["Obrigatório e gratuito", "Pago, com bolsas para os mais pobres", "Opcional, a critério dos pais", "Gratuito só nas capitais"], "explicacao": "Art. 208, I, da CF."}, {"id": 10452, "materia": "const", "nivel": 0, "enunciado": "A liberdade de crença garantida pela Constituição significa que:", "opcoes": ["Cada pessoa pode ter a religião que quiser, ou nenhuma", "O Estado tem uma religião oficial que todos devem seguir", "Todos devem seguir a religião da maioria", "Só religiões registradas podem existir"], "explicacao": "Art. 5º, VI, da CF."}, {"id": 10453, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, o direito de petição aos órgãos públicos é garantido:", "opcoes": ["Sem pagamento de taxas", "Mediante pagamento de taxa", "Só por meio de advogado", "Só a brasileiros natos"], "explicacao": "Art. 5º, XXXIV, a, da CF."}, {"id": 10454, "materia": "const", "nivel": 0, "enunciado": "O habeas corpus pode ser pedido em favor de:", "opcoes": ["Qualquer pessoa presa ilegalmente", "Apenas parentes do advogado", "Apenas servidores públicos", "Apenas quem já tem condenação definitiva"], "explicacao": "Qualquer pessoa pode impetrá-lo, em favor de qualquer pessoa."}, {"id": 10455, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, a família, a sociedade e o Estado têm o dever de amparar:", "opcoes": ["As pessoas idosas", "Só os servidores públicos", "Só os eleitores", "Só os empresários"], "explicacao": "Art. 230 da CF."}, {"id": 10456, "materia": "dh", "nivel": 0, "enunciado": "Os direitos humanos protegem:", "opcoes": ["Todas as pessoas, sem distinção", "Só quem não tem antecedentes criminais", "Só os brasileiros natos", "Só os eleitores"], "explicacao": "Universalidade dos direitos humanos."}, {"id": 10457, "materia": "dh", "nivel": 0, "enunciado": "Pela Declaração Universal, toda pessoa tem direito à liberdade de:", "opcoes": ["Pensamento, consciência e religião", "Descumprir as leis que não aprova", "Deixar de pagar todos os tributos devidos", "Portar armas em qualquer lugar"], "explicacao": "Art. 18 da DUDH."}, {"id": 10458, "materia": "igual", "nivel": 0, "enunciado": "Ofender alguém por causa da cor da pele é, pela lei atual, crime de:", "opcoes": ["Injúria racial, equiparada ao racismo", "Difamação simples, de ação privada", "Contravenção penal, sem pena de prisão alguma", "Ameaça, com pena de detenção"], "explicacao": "Lei 14.532/2023 (art. 2º-A da Lei 7.716/1989)."}, {"id": 10459, "materia": "inf", "nivel": 0, "enunciado": "Para não perder arquivos importantes se o computador quebrar, deve-se:", "opcoes": ["Fazer backup com frequência", "Desligar o antivírus", "Apagar os arquivos antigos", "Deixar tudo na área de trabalho"], "explicacao": "Cópia de segurança em outro local."}, {"id": 10460, "materia": "inf", "nivel": 0, "enunciado": "Usar o Wi-Fi aberto de uma praça é arriscado principalmente para:", "opcoes": ["Acessar a conta do banco", "Ler as notícias do jornal do dia", "Ver a previsão do tempo", "Ouvir uma rádio on-line"], "explicacao": "Redes abertas podem ser interceptadas."}, {"id": 10461, "materia": "inf", "nivel": 0, "enunciado": "No celular, o bloqueio de tela com senha ou digital serve para:", "opcoes": ["Proteger os dados se o aparelho for perdido", "Fazer a bateria durar mais tempo", "Aumentar a velocidade da internet", "Liberar espaço na memória"], "explicacao": "Impede o acesso de terceiros."}, {"id": 10462, "materia": "inf", "nivel": 0, "enunciado": "No celular, o PIN do chip serve para:", "opcoes": ["Impedir o uso do chip por outra pessoa", "Aumentar a velocidade da internet móvel do chip", "Carregar a bateria mais rápido", "Bloquear propagandas nos aplicativos"], "explicacao": "Protege o chip em caso de furto ou perda."}, {"id": 10463, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei de Drogas, o tráfico praticado na porta de uma escola tem a pena:", "opcoes": ["Aumentada", "Reduzida", "Igual", "Trocada por multa"], "explicacao": "Art. 40, III, da Lei 11.343/2006."}, {"id": 10464, "materia": "leg", "nivel": 0, "enunciado": "Pela Lei Maria da Penha, a vítima pode pedir medida protetiva:", "opcoes": ["Na delegacia, que encaminha o pedido ao juiz", "Só pessoalmente, na frente do juiz", "Só por meio de advogado particular", "Só depois de o agressor ser condenado pelo crime"], "explicacao": "Art. 12, III, da Lei 11.340/2006."}, {"id": 10465, "materia": "leg", "nivel": 0, "enunciado": "O Ligue 180 recebe denúncias de violência contra:", "opcoes": ["A mulher", "O consumidor", "O meio ambiente", "Os animais"], "explicacao": "Central de Atendimento à Mulher."}, {"id": 10466, "materia": "leg", "nivel": 0, "enunciado": "Pelo ECA, os membros do Conselho Tutelar são:", "opcoes": ["Escolhidos pela comunidade local", "Policiais militares", "Juízes da Vara da Infância e Juventude", "Promotores de justiça"], "explicacao": "Art. 132 do ECA."}, {"id": 10467, "materia": "leg", "nivel": 0, "enunciado": "Agredir o pai idoso que mora com você pode configurar crime previsto:", "opcoes": ["No Código Penal e no Estatuto da Pessoa Idosa", "Apenas no Código de Trânsito Brasileiro", "Apenas no Estatuto do Desarmamento, por ser violência", "Apenas na Lei de Contravenções Penais"], "explicacao": "Lesão corporal e crimes do Estatuto da Pessoa Idosa."}, {"id": 10468, "materia": "leg", "nivel": 0, "enunciado": "Pescar usando explosivos é crime:", "opcoes": ["Ambiental", "De trânsito", "Contra a honra", "Contra o patrimônio"], "explicacao": "Art. 35 da Lei 9.605/1998."}, {"id": 10469, "materia": "leg", "nivel": 0, "enunciado": "Quem tem arma registrada em casa pode levá-la para o trabalho?", "opcoes": ["Não, o registro não dá direito ao porte", "Sim, sempre que quiser", "Sim, se o chefe autorizar por escrito", "Sim, se estiver descarregada"], "explicacao": "Registro permite a posse em casa; o porte depende de autorização própria."}, {"id": 10470, "materia": "leg", "nivel": 0, "enunciado": "Entre as medidas protetivas que o juiz pode impor ao agressor está:", "opcoes": ["Manter distância mínima da vítima", "Pagar fiança fixada pela própria vítima", "Ficar preso em casa por um ano, sempre", "Mudar de cidade em 24 horas"], "explicacao": "Art. 22, III, a, da Lei 11.340/2006."}, {"id": 10471, "materia": "ml", "nivel": 0, "enunciado": "O exame de corpo de delito é feito, em regra, por:", "opcoes": ["Perito oficial", "Policial militar", "Delegado", "Escrivão"], "explicacao": "Art. 159 do CPP."}, {"id": 10472, "materia": "ml", "nivel": 0, "enunciado": "As impressões digitais são diferentes de uma pessoa para outra, inclusive entre:", "opcoes": ["Gêmeos idênticos", "Apenas homens", "Apenas adultos", "Apenas estranhos"], "explicacao": "Por isso servem para identificação."}, {"id": 10473, "materia": "pcd", "nivel": 0, "enunciado": "Estacionar sem credencial em vaga reservada a pessoa com deficiência é:", "opcoes": ["Infração de trânsito gravíssima", "Crime de trânsito", "Permitido por 5 minutos", "Infração de trânsito leve, só com advertência"], "explicacao": "Art. 181, XX, do CTB."}, {"id": 10474, "materia": "pen", "nivel": 0, "enunciado": "Rafael pega a moto do vizinho sem que ninguém veja e vai embora com ela. Rafael comete:", "opcoes": ["Furto", "Roubo", "Receptação", "Apropriação indébita"], "explicacao": "Subtração sem violência nem grave ameaça: art. 155 do CP."}, {"id": 10475, "materia": "pen", "nivel": 0, "enunciado": "Numa discussão, uma mulher dá um tapa no rosto de outra, sem deixar nenhuma marca. Isso pode configurar:", "opcoes": ["Vias de fato", "Lesão corporal grave", "Tentativa de homicídio", "Injúria racial"], "explicacao": "Art. 21 da Lei das Contravenções Penais: agressão sem lesão."}, {"id": 10476, "materia": "pen", "nivel": 0, "enunciado": "Quem vai à delegacia dizer que foi assaltado, sabendo que nada aconteceu, comete:", "opcoes": ["Comunicação falsa de crime", "Denunciação caluniosa contra terceiro", "Falso testemunho", "Fraude processual"], "explicacao": "Art. 340 do CP. Se acusar uma pessoa determinada, pode ser denunciação caluniosa."}, {"id": 10477, "materia": "pen", "nivel": 0, "enunciado": "Parado numa blitz, Carlos diz ao policial um nome falso para esconder que tem mandado de prisão. Ele comete:", "opcoes": ["Falsa identidade", "Falsidade ideológica", "Uso de documento falso", "Desobediência"], "explicacao": "Art. 307 do CP e Súmula 522 do STJ."}, {"id": 10478, "materia": "pen", "nivel": 0, "enunciado": "Quebrar de propósito o vidro de uma viatura da polícia é crime de:", "opcoes": ["Dano qualificado", "Dano simples", "Furto qualificado", "Desacato"], "explicacao": "Art. 163, parágrafo único, III, do CP: dano a patrimônio público."}, {"id": 10479, "materia": "pen", "nivel": 0, "enunciado": "Quem mata alguém para receber a herança comete homicídio:", "opcoes": ["Qualificado, por motivo torpe", "Privilegiado, por relevante valor", "Culposo, por imprudência", "Simples, sem qualificadora"], "explicacao": "Art. 121, § 2º, I, do CP."}, {"id": 10480, "materia": "pen", "nivel": 0, "enunciado": "Uma mãe deixa o filho de 3 anos sozinho em casa o dia inteiro para viajar. Ela pode responder por:", "opcoes": ["Abandono de incapaz", "Abandono material", "Omissão de socorro a menor", "Maus-tratos"], "explicacao": "Art. 133 do CP."}, {"id": 10481, "materia": "port", "nivel": 0, "enunciado": "Assinale a frase com a grafia correta:", "opcoes": ["A viagem foi longa.", "A viajem foi longa.", "A viágem foi longa.", "A viajen foi longa."], "explicacao": "O substantivo é “viagem”; “viajem” é verbo."}, {"id": 10482, "materia": "port", "nivel": 0, "enunciado": "O plural de “alemão” é:", "opcoes": ["Alemães", "Alemãos", "Alemões", "Alemans"], "explicacao": "Alemão, alemães."}, {"id": 10483, "materia": "port", "nivel": 0, "enunciado": "O feminino de “cidadão” é:", "opcoes": ["Cidadã", "Cidadona", "Cidadoa", "Cidadana"], "explicacao": "Cidadão, cidadã."}, {"id": 10484, "materia": "port", "nivel": 0, "enunciado": "Em “O suspeito fugiu rapidamente”, a palavra “rapidamente” é:", "opcoes": ["Advérbio", "Adjetivo", "Verbo", "Substantivo"], "explicacao": "Indica o modo da ação."}, {"id": 10485, "materia": "port", "nivel": 0, "enunciado": "O sinônimo de “ludibriar” é:", "opcoes": ["Enganar", "Ajudar", "Prender", "Esclarecer"], "explicacao": "Ludibriar: iludir, enganar."}, {"id": 10486, "materia": "ppen", "nivel": 0, "enunciado": "Logo após um assalto, a vítima e os policiais correm atrás do ladrão e o prendem duas ruas depois. Esse é o flagrante:", "opcoes": ["Impróprio", "Próprio", "Presumido", "Preparado"], "explicacao": "Art. 302, III, do CPP: perseguição logo após o crime."}, {"id": 10487, "materia": "ppen", "nivel": 0, "enunciado": "Quem preside a audiência de custódia é o:", "opcoes": ["Juiz", "Delegado", "Promotor", "Defensor"], "explicacao": "Art. 310 do CPP."}, {"id": 10488, "materia": "ppen", "nivel": 0, "enunciado": "O preso tem direito de ser assistido por:", "opcoes": ["Advogado ou defensor público", "Um policial de sua confiança", "O promotor do caso", "O escrivão de plantão"], "explicacao": "Art. 5º, LXIII, da CF."}, {"id": 10489, "materia": "ppen", "nivel": 0, "enunciado": "Antes de ouvir o preso, o delegado deve informá-lo do direito de:", "opcoes": ["Ficar calado", "Escolher o juiz", "Sair na hora", "Fixar a fiança"], "explicacao": "Art. 5º, LXIII, da CF e art. 186 do CPP."}, {"id": 10490, "materia": "ppen", "nivel": 0, "enunciado": "A faca usada no crime, encontrada no local, deve ser:", "opcoes": ["Apreendida e enviada à perícia", "Devolvida ao dono na hora", "Lavada para ser guardada com segurança", "Entregue à família da vítima"], "explicacao": "Art. 6º, II, do CPP."}, {"id": 10491, "materia": "ppen", "nivel": 0, "enunciado": "No inquérito policial, quem ouve as testemunhas é, em regra, a:", "opcoes": ["Autoridade policial", "Defensoria Pública", "Promotoria de justiça", "Vara criminal"], "explicacao": "Art. 6º, III a V, do CPP."}, {"id": 10492, "materia": "rl", "nivel": 0, "enunciado": "Qual o próximo número da sequência 100, 90, 80, 70, …?", "opcoes": ["60", "65", "50", "75"], "explicacao": "Tira-se 10 a cada termo."}, {"id": 10493, "materia": "rl", "nivel": 0, "enunciado": "Um plantão de 24 horas começa às 7h de segunda-feira. Ele termina:", "opcoes": ["Às 7h de terça-feira", "Às 19h de segunda-feira", "Às 7h de quarta-feira", "Às 19h de terça-feira"], "explicacao": "24 horas depois é o mesmo horário do dia seguinte."}, {"id": 10494, "materia": "rl", "nivel": 0, "enunciado": "Um policial faz 4 rondas por noite. Em 7 noites, ele faz:", "opcoes": ["28 rondas", "24 rondas", "32 rondas", "21 rondas"], "explicacao": "4 × 7."}, {"id": 10495, "materia": "rl", "nivel": 0, "enunciado": "Metade de 50 mais o dobro de 10 é:", "opcoes": ["45", "35", "70", "40"], "explicacao": "25 + 20."}, {"id": 10496, "materia": "rl", "nivel": 0, "enunciado": "Todo agente usa colete. Paulo não usa colete. Logo:", "opcoes": ["Paulo não é agente", "Paulo é agente", "Todo agente é Paulo", "Nada se conclui"], "explicacao": "Se fosse agente, usaria colete."}, {"id": 10497, "materia": "adm", "nivel": 1, "enunciado": "Interditar um restaurante sujo, sem ordem judicial, é exemplo de:", "opcoes": ["Poder de polícia com autoexecutoriedade", "Poder disciplinar sobre o dono do restaurante", "Poder hierárquico sobre o dono", "Poder regulamentar do prefeito"], "explicacao": "A Administração executa a medida por conta própria."}, {"id": 10498, "materia": "adm", "nivel": 1, "enunciado": "O servidor que pede exoneração:", "opcoes": ["Deixa o cargo a pedido, sem punição", "É demitido por abandono do cargo público", "Perde a aposentadoria já concedida", "Precisa devolver todos os salários"], "explicacao": "Exoneração não é penalidade."}, {"id": 10499, "materia": "adm", "nivel": 1, "enunciado": "A Administração pode revogar um ato:", "opcoes": ["Válido, por conveniência e oportunidade", "Ilegal, por conveniência e oportunidade", "Já anulado por decisão judicial", "Praticado por outro Poder"], "explicacao": "Ato ilegal é anulado, não revogado."}, {"id": 10500, "materia": "adm", "nivel": 1, "enunciado": "Remover um servidor de ofício só para puni-lo, sem interesse do serviço, configura:", "opcoes": ["Desvio de finalidade", "Uso regular do poder hierárquico", "Ato vinculado e válido", "Revogação legítima do ato"], "explicacao": "A remoção não é penalidade; usá-la para punir desvia o fim do ato."}, {"id": 10501, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, o trabalho noturno, perigoso ou insalubre é proibido a menores de:", "opcoes": ["18 anos", "16 anos", "14 anos", "21 anos"], "explicacao": "Art. 7º, XXXIII, da CF."}, {"id": 10502, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, qualquer trabalho é proibido a menores de 16 anos, salvo na condição de:", "opcoes": ["Aprendiz, a partir de 14 anos", "Estagiário, a partir de 12 anos", "Autônomo, a partir de 10 anos", "Doméstico, a partir de 15 anos"], "explicacao": "Art. 7º, XXXIII, da CF."}, {"id": 10503, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, a prisão ilegal será imediatamente:", "opcoes": ["Relaxada pelo juiz", "Mantida até a sentença", "Convertida em domiciliar", "Comunicada só à família"], "explicacao": "Art. 5º, LXV, da CF."}, {"id": 10504, "materia": "const", "nivel": 1, "enunciado": "Pela Constituição, além do direito de resposta proporcional ao agravo, é assegurada:", "opcoes": ["Indenização por dano material, moral ou à imagem", "A prisão imediata de quem fez a ofensa", "A censura prévia de futuras publicações", "A retirada do jornal de circulação no país"], "explicacao": "Art. 5º, V, da CF."}, {"id": 10505, "materia": "const", "nivel": 1, "enunciado": "Pelo princípio da inafastabilidade, a lei não excluirá da apreciação do Judiciário:", "opcoes": ["Lesão ou ameaça a direito", "Apenas lesões já consumadas", "Só os casos criminais", "Só causas de alto valor"], "explicacao": "Art. 5º, XXXV, da CF."}, {"id": 10506, "materia": "dh", "nivel": 1, "enunciado": "Pela Lei 13.060/2014, o uso da força pelos policiais deve obedecer aos princípios da:", "opcoes": ["Legalidade, necessidade, razoabilidade e proporcionalidade", "Vontade do comandante e gravidade da ocorrência atendida", "Opinião da vítima e do histórico do suspeito", "Rapidez, surpresa e superioridade numérica"], "explicacao": "Art. 2º da Lei 13.060/2014."}, {"id": 10507, "materia": "dh", "nivel": 1, "enunciado": "Pela Lei 13.060/2014, não é legítimo o uso de arma de fogo contra:", "opcoes": ["Pessoa em fuga, desarmada, que não ofereça risco imediato", "Agressor que está atirando contra os policiais na rua", "Pessoa que ameaça matar um refém com uma faca", "Criminoso armado que atira contra a população"], "explicacao": "Art. 2º, parágrafo único, I, da Lei 13.060/2014."}, {"id": 10508, "materia": "igual", "nivel": 1, "enunciado": "Pela Lei 7.716/1989, impedir alguém de usar o elevador social por preconceito de raça é:", "opcoes": ["Crime", "Infração civil", "Contravenção", "Fato atípico"], "explicacao": "Art. 11 da Lei 7.716/1989."}, {"id": 10509, "materia": "inf", "nivel": 1, "enunciado": "No Excel, a fórmula =A1*B1 calcula:", "opcoes": ["A multiplicação de A1 por B1", "A soma de A1 com B1", "A divisão de A1 por B1", "A potência de A1 elevado a B1"], "explicacao": "O asterisco é o sinal de multiplicação."}, {"id": 10510, "materia": "inf", "nivel": 1, "enunciado": "O golpe do falso parente no WhatsApp, que pede Pix urgente de um número novo, é exemplo de:", "opcoes": ["Engenharia social", "Ransomware (sequestro de dados)", "Worm", "Ataque DDoS"], "explicacao": "Manipula a confiança da vítima."}, {"id": 10511, "materia": "inf", "nivel": 1, "enunciado": "Ao usar Ctrl + C e depois Ctrl + V em um arquivo, o resultado é:", "opcoes": ["Uma cópia do arquivo no novo local", "A exclusão do arquivo original", "A mudança do arquivo de lugar", "A compactação do arquivo em formato ZIP"], "explicacao": "Ctrl + X e Ctrl + V movem o arquivo."}, {"id": 10512, "materia": "inf", "nivel": 1, "enunciado": "Na internet, um endereço terminado em .gov.br indica, em regra, site de:", "opcoes": ["Órgão público brasileiro", "Empresa privada nacional", "Organização não governamental", "Universidade estrangeira"], "explicacao": "Domínio reservado ao governo."}, {"id": 10513, "materia": "leg", "nivel": 1, "enunciado": "O motorista com sinais claros de embriaguez que recusa o bafômetro pode ter a embriaguez provada, para o crime, por:", "opcoes": ["Vídeos, testemunhas e exame clínico", "Apenas o teste do bafômetro", "Só exame de sangue com ordem judicial", "Nada, pois ele não pode ser punido"], "explicacao": "Art. 306, § 2º, do CTB."}, {"id": 10514, "materia": "leg", "nivel": 1, "enunciado": "Pelo Estatuto do Desarmamento, vender arma de fogo a menor de 18 anos é:", "opcoes": ["Crime", "Infração apenas administrativa", "Permitido, se os pais autorizarem", "Contravenção penal"], "explicacao": "Art. 16, § 1º, V, da Lei 10.826/2003."}, {"id": 10515, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei Maria da Penha, impedir a mulher de usar qualquer método contraceptivo é violência:", "opcoes": ["Sexual", "Moral", "Patrimonial", "Física"], "explicacao": "Art. 7º, III, da Lei 11.340/2006."}, {"id": 10516, "materia": "leg", "nivel": 1, "enunciado": "Pelo ECA, a apreensão do adolescente deve ser comunicada imediatamente:", "opcoes": ["Ao juiz e à família ou à pessoa indicada", "Só ao Conselho Tutelar da cidade onde mora", "Só ao diretor da escola dele", "Ao prefeito e à imprensa local"], "explicacao": "Art. 107 do ECA."}, {"id": 10517, "materia": "leg", "nivel": 1, "enunciado": "Pelo Estatuto da Pessoa Idosa, divulgar imagens que humilhem ou ridicularizem o idoso é:", "opcoes": ["Crime", "Infração civil", "Contravenção", "Fato atípico"], "explicacao": "Art. 105 da Lei 10.741/2003."}, {"id": 10518, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei 9.605/1998, destruir floresta de preservação permanente é:", "opcoes": ["Crime ambiental", "Apenas infração civil", "Contravenção penal", "Fato atípico"], "explicacao": "Art. 38 da Lei 9.605/1998."}, {"id": 10519, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei de Tortura, a pena é aumentada se o crime for cometido por:", "opcoes": ["Agente público", "Pessoa maior de 60 anos", "Estrangeiro", "Réu primário"], "explicacao": "Art. 1º, § 4º, I, da Lei 9.455/1997."}, {"id": 10520, "materia": "ml", "nivel": 1, "enunciado": "O exame toxicológico serve para identificar:", "opcoes": ["Drogas, álcool ou venenos no organismo", "A idade aproximada da vítima pelos ossos", "A causa de uma fratura óssea", "O tipo sanguíneo da pessoa"], "explicacao": "Análise de sangue, urina ou tecidos."}, {"id": 10521, "materia": "ml", "nivel": 1, "enunciado": "O odontolegista é o perito que examina principalmente:", "opcoes": ["Dentes e arcada dentária", "Impressões digitais", "Projéteis e estojos", "Documentos e assinaturas"], "explicacao": "Ajuda a identificar corpos e a estimar idade."}, {"id": 10522, "materia": "pcd", "nivel": 1, "enunciado": "Pela LBI, a pessoa com deficiência pode ser obrigada a se tratar ou ser internada sem dar seu consentimento?", "opcoes": ["Não, em regra é preciso o consentimento dela", "Sim, sempre que a família pedir ao hospital ou clínica", "Sim, se o médico achar melhor para ela", "Sim, se ela tiver mais de 60 anos"], "explicacao": "Arts. 11 e 12 da Lei 13.146/2015."}, {"id": 10523, "materia": "pen", "nivel": 1, "enunciado": "Pedro entrega a carteira ao assaltante que diz estar armado, mas a arma era de brinquedo. O crime é:", "opcoes": ["Roubo, pela grave ameaça", "Furto, pois a arma não era real", "Estelionato, pelo engano da vítima", "Extorsão, porque Pedro entregou"], "explicacao": "A arma de brinquedo intimida: há grave ameaça. Não incide o aumento por arma de fogo."}, {"id": 10524, "materia": "pen", "nivel": 1, "enunciado": "Dois amigos combinam um furto: um vigia a rua enquanto o outro entra na casa. Quem vigiou responde:", "opcoes": ["Pelo furto, pois concorreu para o crime", "Por nada, pois não entrou na casa da vítima", "Por favorecimento real", "Por receptação"], "explicacao": "Art. 29 do CP: quem concorre para o crime incide nas suas penas."}, {"id": 10525, "materia": "pen", "nivel": 1, "enunciado": "Lúcia escreve no grupo do prédio que o síndico desviou o dinheiro do condomínio, sabendo que é mentira. Ela comete:", "opcoes": ["Calúnia", "Difamação", "Injúria", "Denunciação caluniosa"], "explicacao": "Imputa falsamente um fato definido como crime: art. 138 do CP."}, {"id": 10526, "materia": "pen", "nivel": 1, "enunciado": "Um homem tranca a ex-namorada em casa por dois dias, impedindo-a de sair. Ele comete:", "opcoes": ["Sequestro e cárcere privado", "Constrangimento ilegal", "Extorsão mediante sequestro", "Ameaça"], "explicacao": "Art. 148 do CP. Não há pedido de resgate, o que caracterizaria a extorsão mediante sequestro."}, {"id": 10527, "materia": "pen", "nivel": 1, "enunciado": "Gustavo dirige acima do limite, sem querer matar ninguém, e atropela e mata um pedestre. Em regra, ele responde por:", "opcoes": ["Homicídio culposo na direção de veículo", "Homicídio doloso qualificado", "Lesão corporal seguida de morte", "Homicídio privilegiado"], "explicacao": "Art. 302 do CTB. Casos de racha podem levar à discussão de dolo eventual."}, {"id": 10528, "materia": "pen", "nivel": 1, "enunciado": "No roubo, manter a vítima amarrada e presa enquanto os ladrões agem:", "opcoes": ["Aumenta a pena", "Transforma em furto", "Não altera a pena", "Exclui o roubo"], "explicacao": "Art. 157, § 2º, V, do CP: restrição da liberdade da vítima."}, {"id": 10529, "materia": "pen", "nivel": 1, "enunciado": "Para cobrar uma dívida, Jorge entra na casa da vizinha e leva a TV dela à força. Em vez de roubo, a doutrina aponta:", "opcoes": ["Exercício arbitrário das próprias razões", "Furto qualificado pela escalada", "Extorsão", "Apropriação indébita"], "explicacao": "Art. 345 do CP: buscou satisfazer pretensão que entendia legítima, fazendo justiça com as próprias mãos."}, {"id": 10530, "materia": "pen", "nivel": 1, "enunciado": "Durante um assalto, o ladrão atira e mata o motorista para levar o carro. O crime é:", "opcoes": ["Latrocínio", "Homicídio qualificado", "Roubo simples", "Extorsão"], "explicacao": "Art. 157, § 3º, II, do CP."}, {"id": 10531, "materia": "port", "nivel": 1, "enunciado": "Assinale a frase correta:", "opcoes": ["Ele interveio na briga.", "Ele interviu na briga.", "Ele interveiu na briga.", "Ele intervio na briga."], "explicacao": "“Intervir” se conjuga como “vir”: ele veio, ele interveio."}, {"id": 10532, "materia": "port", "nivel": 1, "enunciado": "Assinale a frase correta quanto a “mal” e “mau”:", "opcoes": ["O suspeito agiu mal.", "O suspeito agiu mau.", "Ele é um mal policial.", "Foi um mau-entendido."], "explicacao": "“Mal” é advérbio (oposto de bem); “mau”, adjetivo (oposto de bom); escreve-se “mal-entendido”."}, {"id": 10533, "materia": "port", "nivel": 1, "enunciado": "Assinale a frase correta quanto a “a” e “há”:", "opcoes": ["O crime ocorreu há duas semanas.", "O crime ocorreu a duas semanas.", "Daqui há duas semanas sai o laudo.", "Há duas semanas atrás saiu o laudo."], "explicacao": "“Há” para tempo passado; “daqui a” para futuro; “há… atrás” é redundante."}, {"id": 10534, "materia": "port", "nivel": 1, "enunciado": "Em “Os policiais chegaram, mas o suspeito já tinha fugido”, a conjunção “mas” indica:", "opcoes": ["Oposição", "Causa", "Conclusão", "Explicação"], "explicacao": "Conjunção adversativa."}, {"id": 10535, "materia": "port", "nivel": 1, "enunciado": "Assinale a frase em que o verbo concorda corretamente:", "opcoes": ["Os agentes e o delegado chegaram.", "Os agentes e o delegado chegou.", "Existe muitas provas no processo.", "Haviam muitos agentes no local."], "explicacao": "Sujeito composto anteposto leva o verbo ao plural; “existir” concorda; “haver” (existir) é impessoal."}, {"id": 10536, "materia": "ppen", "nivel": 1, "enunciado": "Um homem é preso em flagrante por furto simples (pena de 1 a 4 anos). Depois do auto, o delegado pode:", "opcoes": ["Arbitrar fiança, pois a pena máxima não passa de 4 anos", "Arquivar o inquérito por se tratar de crime leve", "Soltar o preso sem fazer nenhum registro", "Mandar o preso prestar serviços à comunidade"], "explicacao": "Art. 322 do CPP."}, {"id": 10537, "materia": "ppen", "nivel": 1, "enunciado": "Diante de uma denúncia anônima de tráfico, a polícia deve, segundo os tribunais:", "opcoes": ["Fazer diligências preliminares antes de instaurar o inquérito", "Prender o suspeito na hora, com base só na denúncia", "Entrar na casa do suspeito, mesmo sem mandado judicial", "Arquivar a denúncia, pois ela não tem valor algum"], "explicacao": "A denúncia anônima, sozinha, não basta para instaurar inquérito nem para entrar em casa."}, {"id": 10538, "materia": "ppen", "nivel": 1, "enunciado": "O investigado pode se recusar a participar da reconstituição do crime?", "opcoes": ["Sim, ninguém é obrigado a produzir prova contra si", "Não, a participação dele é sempre obrigatória por lei", "Só se o juiz autorizar a recusa por escrito", "Só se ele tiver menos de 21 anos de idade"], "explicacao": "Princípio da não autoincriminação."}, {"id": 10539, "materia": "ppen", "nivel": 1, "enunciado": "Um policial civil de folga vê um roubo acontecendo na rua. Pela lei, ele:", "opcoes": ["Deve agir para prender o autor, pois tem esse dever", "Só pode agir se estiver fardado e em serviço", "Não pode fazer nada fora do horário de trabalho", "Deve apenas filmar e chamar a polícia militar"], "explicacao": "Art. 301 do CPP: as autoridades policiais e seus agentes deverão prender quem estiver em flagrante."}, {"id": 10540, "materia": "ppen", "nivel": 1, "enunciado": "Entre as funções da polícia judiciária está:", "opcoes": ["Cumprir os mandados de prisão expedidos pelo juiz", "Julgar os crimes de menor potencial ofensivo da comarca", "Oferecer a denúncia ao juiz", "Fixar a pena do condenado"], "explicacao": "Art. 13, III, do CPP."}, {"id": 10541, "materia": "ppen", "nivel": 1, "enunciado": "No inquérito, a vítima pode pedir ao delegado que faça diligências?", "opcoes": ["Sim, e o delegado decide se vai realizá-las", "Não, a vítima não participa de nenhuma fase do inquérito", "Sim, e o delegado é obrigado a fazer todas", "Só por meio de petição dirigida ao juiz"], "explicacao": "Art. 14 do CPP."}, {"id": 10542, "materia": "rl", "nivel": 1, "enunciado": "Um delegado divide 36 inquéritos igualmente entre 4 escrivães e depois dá mais 2 a cada um. Quantos cada um fica?", "opcoes": ["11", "9", "13", "10"], "explicacao": "36 / 4 = 9; 9 + 2 = 11."}, {"id": 10543, "materia": "rl", "nivel": 1, "enunciado": "Num grupo de 30 presos, 2/5 trabalham na cozinha. Quantos não trabalham na cozinha?", "opcoes": ["18", "12", "20", "15"], "explicacao": "2/5 de 30 = 12; 30 − 12 = 18."}, {"id": 10544, "materia": "rl", "nivel": 1, "enunciado": "A negação de “Nenhum suspeito foi liberado” é:", "opcoes": ["Algum suspeito foi liberado", "Todos os suspeitos foram liberados", "Nenhum suspeito ficou preso", "Algum suspeito não foi liberado"], "explicacao": "A negação de “nenhum” é “algum”."}, {"id": 10545, "materia": "rl", "nivel": 1, "enunciado": "Se “Ana é escrivã” é falsa e “Beto é perito” é verdadeira, a proposição “Ana é escrivã ou Beto é perito” é:", "opcoes": ["Verdadeira", "Falsa", "Indeterminada", "Contraditória"], "explicacao": "Basta uma parte verdadeira na disjunção."}, {"id": 10546, "materia": "rl", "nivel": 1, "enunciado": "Uma viatura roda 240 km com 20 litros. Para rodar 360 km, gasta:", "opcoes": ["30 litros", "28 litros", "32 litros", "36 litros"], "explicacao": "12 km por litro; 360 / 12."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select nivel, count(*) as questoes_novas from public.questoes where id between 10447 and 10546 group by nivel order by nivel;
select public.questoes_versao() as nova_versao;
